-- Проверяет обязательность/уникальность ключей и существование родителей; нарушение блокирует дочерние шаги.
SELECT count(*) n FROM (SELECT original_batch_id FROM {{target:oil_stg__batch_coalesce_map}} GROUP BY original_batch_id HAVING original_batch_id IS NULL OR count(*)<>1 UNION ALL SELECT m.original_batch_id FROM {{target:oil_stg__batch_coalesce_map}} m LEFT JOIN {{target:oil_stg__batch_control}} a ON a.batch_id=m.original_batch_id LEFT JOIN {{target:oil_stg__batch_control}} b ON b.batch_id=m.coalesced_batch_id WHERE a.batch_id IS NULL OR b.batch_id IS NULL OR m.coalesced_batch_id IS NULL) q;
